const http = require('node:http');
const https = require('node:https');
const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
const requestTimeoutMs = Number($env.AUTOMATION_RUNNER_REQUEST_TIMEOUT_MS || 30000);
if (!runnerBase) throw new Error('AUTOMATION_RUNNER_BASE_URL is not configured');

const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};

const request = (urlString, options = {}) => new Promise((resolve, reject) => {
  const transport = String(urlString).startsWith('https://') ? https : http;
  const timeoutMs = Number(options.timeoutMs || requestTimeoutMs);
  const req = transport.request(urlString, {
    method: options.method || 'GET',
    headers: options.headers || {},
  }, (res) => {
    let body = '';
    res.on('data', (chunk) => {
      body += chunk.toString();
    });
    res.on('end', () => {
      resolve({
        statusCode: res.statusCode || 0,
        body,
      });
    });
  });
  req.setTimeout(timeoutMs, () => {
    req.destroy(new Error(`Request timed out after ${timeoutMs}ms: ${urlString}`));
  });
  req.on('error', reject);
  if (options.body) {
    req.write(options.body);
  }
  req.end();
});

const parseJson = (value, fallback, contextLabel) => {
  if (!value) {
    return fallback;
  }
  try {
    return JSON.parse(value);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Could not parse JSON from ${contextLabel}: ${message}`);
  }
};

const statusResponse = await request(`${runnerBase}/repo/status`, { headers });
if (statusResponse.statusCode < 200 || statusResponse.statusCode >= 300) {
  throw new Error(`Runner repo status failed: ${statusResponse.statusCode} ${statusResponse.body}`);
}
const repoStatus = parseJson(statusResponse.body, {}, 'repo/status');

let action = 'noop';
let reason = 'Main is already clean.';
let promotionResult = null;
let sweepResult = null;

if (repoStatus.branch === 'main' && !repoStatus.clean) {
  action = 'promote_main_changes';
  reason = 'Dirty main detected; branch, commit, push, and PR promotion will run now.';

  const promotionResponse = await request(`${runnerBase}/jobs`, {
    method: 'POST',
    headers,
    body: JSON.stringify({ action, mode: 'sync', args: [] }),
  });
  if (promotionResponse.statusCode < 200 || promotionResponse.statusCode >= 300) {
    throw new Error(`promote_main_changes failed: ${promotionResponse.statusCode} ${promotionResponse.body}`);
  }
  promotionResult = parseJson(promotionResponse.body, null, 'jobs/promote_main_changes');
} else if (repoStatus.branch !== "main") {
  reason = `Repository is on ${repoStatus.branch}; skipping dirty-main promotion but still launching the repo-wide PR sweep.`;
} else {
  reason = 'Main is clean; launch the open PR sweep to keep automation-created branches progressing toward merge.';
}

const sweepResponse = await request(`${runnerBase}/jobs`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ action: 'pr_sweep_open', mode: 'async', args: [], dedupeKey: 'open-pr-sweep' }),
});
if (![200, 202].includes(sweepResponse.statusCode)) {
  throw new Error(`pr_sweep_open failed: ${sweepResponse.statusCode} ${sweepResponse.body}`);
}
sweepResult = parseJson(sweepResponse.body, null, 'jobs/pr_sweep_open');

const timestamp = new Date().toISOString().replace(/[:]/g, '-');
const reportRelativePath = `main-clean-check/${timestamp}.md`;
const reportContent = [
  '# Main Clean Check',
  '',
  `Generated: ${new Date().toISOString()}`
  ,`Branch: ${repoStatus.branch}`
  ,`Working tree clean: ${repoStatus.clean}`
  ,'',
  `Action: ${action}`
  ,reason,
  '',
  '## Repo Status',
  '',
  '```json',
  JSON.stringify(repoStatus, null, 2),
  '```',
  '',
  '## Promotion Result',
  '',
  promotionResult ? '```json\n' + JSON.stringify(promotionResult, null, 2) + '\n```' : 'No branch promotion was needed.',
  '',
  '## Sweep Result',
  '',
  sweepResult ? '```json\n' + JSON.stringify(sweepResult, null, 2) + '\n```' : 'No sweep job was launched.',
].join('\n');

const writeResponse = await request(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: reportContent }),
});
if (writeResponse.statusCode < 200 || writeResponse.statusCode >= 300) {
  throw new Error(`Runner report write failed: ${writeResponse.statusCode} ${writeResponse.body}`);
}

return [{
  json: {
    generatedAt: new Date().toISOString(),
    action,
    reason,
    reportRelativePath,
    repoStatus,
    promotionResult,
    sweepResult,
  },
}];
